// Generated by tack build. Do not edit. Sends each guarded Bash call and each
// tack tool run to tack-hook as one NDJSON line, and fails closed.

const TOOLS = [{"description":"Reports whether the tack daemon is running","inputSchema":{"type":"object"},"isDeferred":false,"name":"guard_status"}];
const HOOK_BIN = "tack-hook";
const PLUGIN_DIR = "/plugins/safe-push";
const DENY_REASONS = ["socket_missing","timeout","socket_closed","malformed_reply","protocol_version","limit","script","unknown_tool","daemon_error","aborted","unsupported_hook","socket_untrusted"];
const PROTOCOL_VERSION = 1;
const BUDGET_MS = 9000;
const TOOL_PREFIX = "mcp__tack__";

const KINDS = new Set(["hook", "tool", "error"]);
const REASONS = new Set(DENY_REASONS);

// Keys Claude Code puts on a tool.call event beside the tool's own arguments.
const RESERVED = new Set([
  "tool",
  "tool_use_id",
  "agentId",
  "consent",
  "requestMeta",
]);

let sequence = 0;
let clockReady = false;

function nextId() {
  sequence = (sequence + 1) % Number.MAX_SAFE_INTEGER;
  return sequence;
}

// A reason the protocol does not declare degrades to the safe fallback.
function denyName(name) {
  return REASONS.has(name) ? name : "malformed_reply";
}

// A Reply::Error class named like a deny reason keeps its name; the rest are
// the daemon's own failures.
function errorReason(kind) {
  return REASONS.has(kind) ? kind : "daemon_error";
}

function refuse(name) {
  return { ok: false, reason: denyName(name) };
}

function denial(reason) {
  return { deny: "tack: " + reason };
}

function delay(ms, least) {
  const value = Number(ms);
  return Number.isFinite(value) && value > least ? Math.floor(value) : least;
}

function cancel(timer) {
  if (timer && typeof timer.cancel === "function") timer.cancel();
}

// A hooks module's timers are not the mod clock and it has no queueMicrotask:
// route them all through $.clock, once, from the first hook that runs.
function installClock($) {
  if (clockReady) return;
  clockReady = true;

  globalThis.setTimeout = (fn, ms, ...args) =>
    $.clock.after(delay(ms, 0), () => fn(...args));
  globalThis.clearTimeout = cancel;
  globalThis.setInterval = (fn, ms, ...args) =>
    $.clock.every(delay(ms, 1), () => fn(...args));
  globalThis.clearInterval = cancel;
  globalThis.queueMicrotask = (fn) => {
    $.clock.after(0, fn);
  };
}

function isArgs(value) {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    return false;
  }

  return Object.keys(value).every((key) => !RESERVED.has(key));
}

function toolArgs(e) {
  const args = {};

  for (const [key, value] of Object.entries(e)) {
    if (!RESERVED.has(key)) args[key] = value;
  }

  return args;
}

function lastLine(text) {
  const lines = text.split("\n").filter((line) => line.trim() !== "");
  return lines.length > 0 ? lines[lines.length - 1] : undefined;
}

// The last stdout line is the reply. Anything else, or a reply that does not
// answer this request, is a named deny.
function readReply(request, done) {
  if (!done || typeof done.stdout !== "string" || done.isStdoutTruncated) {
    return refuse("malformed_reply");
  }

  const line = lastLine(done.stdout);

  if (line === undefined) {
    return refuse(done.exitCode === 0 ? "malformed_reply" : "daemon_error");
  }

  let reply;

  try {
    reply = JSON.parse(line);
  } catch {
    return refuse("malformed_reply");
  }

  if (!reply || typeof reply !== "object" || reply.id !== request.id ||
      !KINDS.has(reply.kind)) {
    return refuse("malformed_reply");
  }
  if (reply.version !== PROTOCOL_VERSION) return refuse("protocol_version");
  if (reply.kind === "error") return refuse(errorReason(reply.error));
  if (reply.kind !== request.kind) return refuse("malformed_reply");
  if (done.exitCode !== 0) return refuse("daemon_error");

  return { ok: true, reply };
}

// One tack-hook run per call, bounded by the budget inside Claude Code's
// 10-second hook limit. A run that cannot start or finish is a named deny.
async function forward($, request) {
  const started = Date.now();
  let done;

  try {
    done = await $.process.run([HOOK_BIN, "--plugin", PLUGIN_DIR], {
      stdin: JSON.stringify(request) + "\n",
      timeoutMs: BUDGET_MS,
    });
  } catch {
    const late = Date.now() - started >= BUDGET_MS;
    return refuse(late ? "timeout" : "daemon_error");
  }

  return readReply(request, done);
}

async function judgeBash($, e) {
  const result = await forward($, {
    kind: "hook",
    id: nextId(),
    version: PROTOCOL_VERSION,
    hook: "toolBefore",
    call: {
      tool: "shell",
      name: "Bash",
      input: { command: e.command },
      session_id: null,
    },
  });

  if (!result.ok) return denial(result.reason);

  const outcome = result.reply.outcome;

  if (!outcome || typeof outcome !== "object") {
    return denial(denyName("malformed_reply"));
  }
  if (outcome.kind === "allow") return {};
  if (outcome.kind === "deny") return denial(outcome.reason || "denied");
  if (outcome.kind === "rewrite" && isArgs(outcome.input)) {
    return { rewrite: outcome.input };
  }

  return denial(denyName("malformed_reply"));
}

async function guardBash($, e, next) {
  installClock($);
  const verdict = await judgeBash($, e);

  if (verdict.deny !== undefined) return verdict;
  if (verdict.rewrite !== undefined) return next({ ...e, ...verdict.rewrite });

  return next(e);
}

async function runTool($, e, spec) {
  installClock($);
  const result = await forward($, {
    kind: "tool",
    id: nextId(),
    version: PROTOCOL_VERSION,
    name: spec.name,
    input: toolArgs(e),
  });

  if (!result.ok) return denial(result.reason);

  const content = result.reply.content;
  const texts = Array.isArray(content) &&
    content.every((item) => item && typeof item.text === "string");

  if (!texts) return denial(denyName("malformed_reply"));

  return { result: content.map((item) => item.text).join("\n") };
}

// One hook serves every tack tool, since Claude Code loads a hook only as a
// function declared at the top of the file. The tool's name, less the mod
// prefix, picks its spec; a name outside TOOLS is refused.
async function serveTool($, e, next) {
  const name = typeof e.tool === "string" && e.tool.startsWith(TOOL_PREFIX)
    ? e.tool.slice(TOOL_PREFIX.length)
    : undefined;
  const spec = TOOLS.find((tool) => tool.name === name);

  if (spec === undefined) return denial(denyName("unknown_tool"));

  return runTool($, e, spec);
}

// Claude Code skips a hook that throws or overruns, and the call runs. This
// answer stands in its place: a deny unless `next` already ran.
function refuseFailed($, e, next) {
  if (next.called) return next(e);

  const timedOut = next.error && next.error.kind === "timeout";
  return denial(denyName(timedOut ? "timeout" : "daemon_error"));
}

async function registerTools($, e, next) {
  installClock($);
  const started = await next(e);

  for (const spec of TOOLS) {
    await $.tool.register(spec);
  }

  return started;
}

// A session.start hook that throws is skipped without a word, and the
// session runs with no tack tool. Name the failure in the transcript, then
// let the session start: the result is next's, replayed if it already ran.
function logStartFailed($, e, next) {
  const error = next.error || {};
  const detail = error.message ? ": " + error.message : "";

  $.ui.log("tack: session registration failed: " + error.kind + detail);
  return next(e);
}

export const register = (on, options) => {
  on("session.start", registerTools).catch(logStartFailed);
  on("tool.call", { tool: "Bash" }, guardBash).catch(refuseFailed);

  for (const spec of TOOLS) {
    on("tool.call", { tool: TOOL_PREFIX + spec.name }, serveTool).catch(refuseFailed);
  }
};
